from functools import wraps
from time import monotonic

def timed(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        start = monotonic()
        try: return fn(*args, **kwargs)
        finally: metrics.observe(fn.__qualname__, monotonic() - start)
    return wrapper

