class Percentage:
    def __init__(self, value: float): self.value = value
    @property
    def value(self) -> float: return self._value
    @value.setter
    def value(self, value: float) -> None:
        if not 0 <= value <= 100: raise ValueError('0..100 required')
        self._value = float(value)
    def __repr__(self) -> str: return f'Percentage({self.value!r})'

